# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_liter_a import L,LET,H
OB=[['拉丁 oblitterare／obliterare → oblitteratus／obliteratus','使消失、使被遗忘 → 已被抹去的'],['英语 obliterate','抹去、彻底毁掉或遮没']]
WC=[
E('letterhead','英 /ˈletəhed/；美 /ˈletərhed/','信笺抬头；印有抬头的信纸','一张正式信纸最上方，先告诉你“这封信来自谁”。','letter“信” + head“顶部”，在英语中组合成词。',H(LET,'英语 letter + head → letterhead','书信的顶部 → 发信单位的抬头、带抬头信纸'),'公司名、地址和标志常印在信纸顶部，这部分是 letterhead；整个专用信纸也可以这样叫。它是发信方的身份信息，不是正文里 Dear 后面的收信人称呼。','company letterhead；on official letterhead；design a letterhead。','letterhead 是信纸抬头；heading 是更广泛的标题或页首文字。',('Please print the confirmation on company letterhead.','请把确认函打印在公司的抬头信纸上。'),('The new letterhead includes the address and telephone number.','新的信笺抬头包含地址和电话号码。'),sources=['https://en.wiktionary.org/wiki/letterhead']),
E('letterbox','英 /ˈletəbɒks/；美 /ˈletərbɑːks/','信箱；投信口；上下留黑边的宽银幕显示方式','先是让信件进入的箱子或细长开口，后来也让人联想到细长的屏幕画面。','letter“信” + box“箱子”；影视义借用了投信口般的横长外观。',H(LET,'英语 letter + box → letterbox','装信的箱子、投信口 → 横长画面的显示方式'),'英式英语中，letterbox 可以是信箱，也可以是门上的投信口。视频里的 letterbox 通常把较宽的完整画面放进较窄的显示框，上下留出黑边，避免为了填满屏幕而裁掉两侧。具体外观取决于画面和屏幕比例。','put something through the letterbox；a letterbox format。','mailbox 常用于美式信箱；视频中左右留边常称 pillarbox，与上下留边不同。',('The envelope was too thick to fit through the letterbox.','信封太厚，塞不进投信口。'),('The widescreen film is shown in a letterbox format with black bars above and below.','这部宽银幕影片以 letterbox 方式显示，上下留有黑边。'),sources=['https://en.wiktionary.org/wiki/letterbox','https://www.merriam-webster.com/dictionary/letterbox']),
E('lettering','英 /ˈletərɪŋ/；美 /ˈletərɪŋ/','字样；书写或设计字形；给物体写字','把字写到招牌、封面或标签上，同时决定它看起来是什么样子。','letter 的动词义“写上字母” + -ing；也形成表示字样或设计活动的名词。',H(LET,'英语 letter → lettering','给物体写字 → 字样、字形设计或书写过程'),'gold lettering 是金色字样；hand lettering 是用手绘制、安排字形。这个词可以说实际看见的字，也可以说制作这些字的工作。它不限于一个特定字体文件，更强调字在具体作品上的呈现。','bold lettering；gold lettering；hand lettering；lettering on a sign。','lettering 看字形怎样呈现；wording 看用了哪些词、怎样措辞。',('The cover has red lettering on a white background.','封面是白底红字。'),('She practises lettering for signs and greeting cards.','她练习为招牌和贺卡设计字样。'),sources=['https://en.wiktionary.org/wiki/lettering']),
E('newsletter','英 /ˈnjuːzletə/；美 /ˈnuːzletər/','简报；定期通讯；电子订阅通讯','把最近值得告诉一群人的消息，定期装成一封或一份发送出去。','news“消息” + letter“信”，由传递消息的信发展为定期出版或发送的通讯。',H(LET,'英语 news + letter → newsletter','消息信件 → 面向订阅者或成员的定期通讯'),'学校、社区、公司或独立作者都可以发 newsletter。它可以是纸质的，也可以通过电子邮件发送；内容可能是新闻、项目进展或选读文章，并不必然是广告，也不必然每天出版。','subscribe to a newsletter；a monthly newsletter；an email newsletter。','newspaper 通常是面向更广泛公众的报纸；newsletter 常面向某个主题、组织或订阅群体。',('The museum sends a monthly newsletter to its members.','博物馆每月向会员发送一份通讯。'),('I found the article through a newsletter about local history.','我通过一份介绍地方历史的订阅通讯读到了这篇文章。'),sources=['https://en.wiktionary.org/wiki/newsletter']),
E('letterpress','/ˈletərpres/','凸版印刷；与插图相对的正文文字〔后一义较少见〕','让凸起、沾了墨的表面碰到纸上，把字或图形压印出来。','letter“字、印字” + press“压印”，在英语中组成印刷词。',H(LET,'英语 letter + press → letterpress','文字 + 压印 → 凸版印刷；印刷文字'),'letterpress 的关键是着墨的印刷部分高出周围表面，再接触纸张。它可以使用活字，也可以使用其他凸版，不能只理解成一格一格排金属字。另一个较旧的义是书里相对插图而言的正文文字。','letterpress printing；letterpress cards；print by letterpress。','letterpress 是印刷方式；typeface 是字形设计。一本书采用什么字体，与用哪种印刷方式，是两个问题。',('The invitations were printed by letterpress on thick paper.','请柬用凸版印刷印在厚纸上。'),('The workshop demonstrates how ink transfers from a raised surface in letterpress printing.','工作坊演示凸版印刷如何把凸起表面的油墨转印到纸上。'),sources=['https://www.merriam-webster.com/dictionary/letterpress','https://en.wiktionary.org/wiki/letterpress']),
E('obliterate','/əˈblɪtəreɪt/','抹掉；彻底毁掉；遮没到无法辨认','原来还能看见的字迹、痕迹或事物，被擦掉、毁掉或盖到辨认不出来。','来自拉丁 obliteratus／oblitteratus。通常联系 ob- 与 littera，理解为抹去文字；早期语义还受“遗忘”一词影响，最早具体过程不能只靠拆词确定。',OB,'雨水可以 obliterate 足迹，粗笔可以 obliterate 名字，灾害可以 obliterate 建筑。共同点是痕迹或原样几乎不再存在，所以语气比普通 remove 强。学习时可以借“把字涂没”记画面，但不应说所有现代含义都按一个已证实的顺序出现。','obliterate all traces；obliterate a name；be completely obliterated。','erase 常强调擦除或删除；obliterate 强调抹得看不出、毁得不剩原样，也可以只是遮没而非物质彻底消失。',('The heavy rain obliterated our footprints.','大雨把我们的脚印冲得无影无踪。'),('A thick black line obliterated the name on the page.','一道粗黑线把纸上的名字涂得无法辨认。'),sources=['https://www.merriam-webster.com/dictionary/obliterate','https://en.wiktionary.org/wiki/obliterate']),
E('obliteration','/əˌblɪtəˈreɪʃən/','抹除；彻底毁灭；痕迹被遮没','把“抹到不见”的动作或结果，作为一件事单独说出来。','来自晚期拉丁 obliteratio／obliterationem，与 obliterare 同族；今天可和 obliterate 对照，但名词有自己的借入路线。',[['拉丁 obliterare → 晚期拉丁 obliteratio','抹去、使消失 → 抹除、消失'],['英语 obliteration','抹除、彻底毁坏的过程或结果']],'the obliteration of a record 可以是记录被彻底抹掉；the obliteration of a landmark 是地标被毁到难以辨认。它是强烈的名词，不能把普通修改、轻微损伤都叫 obliteration。','complete obliteration；the obliteration of all traces。','obliterate 是做这个动作；obliteration 是动作或结果。它们同源，不等于历史上英语名词一定由英语动词现造。',('The storm caused the obliteration of the old path.','风暴使那条旧小路完全失去了踪迹。'),('The archivist noticed the deliberate obliteration of several names.','档案管理员注意到有几个名字被人刻意抹去了。'),sources=['https://www.etymonline.com/word/obliteration','https://www.merriam-webster.com/dictionary/obliterate']),
E('obliterated','/əˈblɪtəreɪtɪd/','抹掉了的；被彻底毁坏的；obliterate 的过去式和过去分词','看向事情结束后的现场：原来的痕迹已经找不到了。','obliterate + -d；词尾 /t/ 后的过去式结尾读 /ɪd/。',H(OB,'英语 obliterate → obliterated','抹去 → 已抹去、被抹去的'),'The rain obliterated the marks 是雨把痕迹冲掉了；the obliterated marks 则直接说那些已被抹去的痕迹。非正式表达还可用 obliterated 夸张形容大败或醉得厉害，不能脱离语境一律按建筑毁坏理解。','obliterated by rain；completely obliterated；an obliterated inscription。','obliterated 着眼已经发生的结果；obliterating 更突出动作正在进行。',('The inscription was almost completely obliterated by weathering.','那段铭文几乎被风化磨得完全无法辨认。'),('The wave obliterated the pattern we had drawn in the sand.','海浪把我们在沙上画的图案冲没了。'),sources=['https://www.merriam-webster.com/dictionary/obliterate','https://en.wiktionary.org/wiki/obliterated']),
E('obliterating','/əˈblɪtəreɪtɪŋ/','正在抹掉或毁坏；obliterate 的 -ing 形式','不只看最终空白，还看见原有痕迹一点点消失的过程。','obliterate 去末尾 e + -ing。',H(OB,'英语 obliterate → obliterating','抹去、毁坏 → 正在抹去或毁坏的过程'),'obliterating 可以放在进行时里，也可以接在逗号后补充前面动作造成的结果。读到它时，找清是谁在抹除、抹除什么；词尾只改变语法角色，核心仍是让痕迹或原样不再可辨。','be obliterating；obliterating all traces；without obliterating。','obliterating 并不总表示现在正在发生；在过去时叙述里也可以描写当时的过程。',('Water was spreading across the page, obliterating the ink.','水在纸面上扩散，把墨迹洇得辨认不出来。'),('The new paint covered the old sign, obliterating every word.','新刷的油漆盖住旧牌子，把每个字都遮没了。'),sources=['https://www.merriam-webster.com/dictionary/obliterate','https://en.wiktionary.org/wiki/obliterating']),
E('literati','英 /ˌlɪtəˈrɑːtiː/；美 /ˌlɪtəˈrɑːti/','文人；文学知识界人士〔集合用法〕','把写作、读书、评论文学的一群人，作为一个圈子来称呼。','来自拉丁 litterati，原是 litteratus“有学问的、受文字教育的”的复数。',L+[['拉丁 litteratus → 复数 litterati','受文字教育的人 → 有学问的文人群体'],['英语 literati','文人、文学知识界人士']],'the local literati 指当地文人圈。这个词较书面，有时带一点对圈内人的赞许或调侃。它本来就是复数形式，常说 the literati are，不应机械地再添 s 来表示一群人。','the local literati；the literary tastes of the literati。','literati 通常说一群文人；writer 可以是一个具体作者，也更日常。不要把它与 literacy“读写能力”混为一词。',('The café became a meeting place for the local literati.','这家咖啡馆成了当地文人的聚会地点。'),('The new magazine attracted attention among the literati.','这本新杂志引起了文人圈的关注。'),sources=['https://en.wiktionary.org/wiki/literati','https://www.etymonline.com/word/literati']),
E('literator','英 /ˈlɪtəreɪtə/；美 /ˈlɪtəreɪtər/','文人；文学工作者；作家〔少见〕','把一个人看成以文字和文学为业、以书本为伴的人。','接拉丁 litterator“文字教师、文法教师”等词义，最终与 littera 相连；英语中用来指文人或作家。',L+[['拉丁 litterator','文字、文法教育工作者'],['英语 literator','文人、文学工作者、作家']],'旧式传记或文学评论可能称某人为 a literator。现代日常表达一般直接用 writer、author 或 scholar 更清楚。这个词不是“能够读写的普通人”的常用名称，也不是文学界统一的职称。','a professional literator；a celebrated literator。','literator 与 littérateur 意思相近，但拼写和借入形式不同；literati 常指群体，不能靠去掉最后的 i 随便造单数。',('The biography presents him as both a journalist and a literator.','这本传记把他描述为兼具记者与文人身份的人。'),('The old review praised the young literator’s command of language.','那篇旧书评称赞了这位年轻作家驾驭语言的能力。'),sources=['https://www.collinsdictionary.com/dictionary/english/literator','https://www.merriam-webster.com/dictionary/literator']),
E('literatim','/ˌlɪtəˈreɪtɪm/','逐字母地；完全照原文拼写地〔少见〕','抄写时连一个字母也不擅自换，原稿怎样拼就怎样保留。','来自中世纪拉丁 litteratim，接 littera“字母”；不是英语 literate 加随意词尾。',L+[['中世纪拉丁 litteratim','逐字母地'],['英语 literatim','照原拼写逐字母抄录的方式']],'古文献整理中，copy literatim 常表示保留原来的字母和拼写，连旧拼法或明显错字也不自作主张改掉。它强调记录忠实度，不代表编辑认为原文每个说法都正确。','copy literatim；a literatim transcription；reproduce literatim。','verbatim 通常强调逐词照录；literatim 更把镜头拉近到字母与拼写层面。具体标点排版如何处理仍需看编辑规则。',('The editor copied the note literatim, preserving its unusual spelling.','编辑逐字母抄下那张便条，保留了它不寻常的拼写。'),('This appendix reproduces the inscription literatim.','这个附录按原来的字母和拼写收录了那段铭文。'),sources=['https://www.merriam-webster.com/dictionary/literatim','https://en.wiktionary.org/wiki/literatim']),
]
